QueuePut try_push(const Frame& frame) {
    if (frame.size > kMaxPayloadBytes) {
      return QueuePut::invalid;
    }
    std::lock_guard<std::mutex> guard(mutex_);
    if (closed_) {
      return QueuePut::closed;
    }
    if (count_ == Capacity) {
      return QueuePut::full;
    }
    buffer_[(head_ + count_) % Capacity] = frame;
    ++count_;
    return QueuePut::stored;
  }

QueueGet try_pop(Frame& out) {
    std::lock_guard<std::mutex> guard(mutex_);
    if (count_ == 0) {
      return closed_ ? QueueGet::closed : QueueGet::empty;
    }
    out = buffer_[head_];
    head_ = (head_ + 1) % Capacity;
    --count_;
    return QueueGet::item;
  }

void close() {
    std::lock_guard<std::mutex> guard(mutex_);
    closed_ = true;
  }

ThreadLink::ThreadLink(Socket socket)
    : worker_([this, owned = std::move(socket)]() mutable {
          const LinkReport result = run(owned);
          owned.reset(); // Close in the owning thread, before publishing completion.
          outbound_.close();
          inbound_.close(); // Already queued frames can still be drained.
          std::lock_guard<std::mutex> lock(report_mutex_);
          report_ = result;
      }

ReceiveAttempt try_receive(Socket& socket, std::uint8_t* data,
                           std::size_t count) noexcept {
  if (!socket.valid() || data == nullptr || count == 0) {
    return ReceiveAttempt{ReceiveState::error, 0, invalid_argument_error()};
  }

  const int request = io_chunk_size(count);
  const auto received =
      ::recv(socket.native(), reinterpret_cast<char*>(data), request, 0);

  if (received > 0) {
    return ReceiveAttempt{ReceiveState::progress,
                          static_cast<std::size_t>(received), 0};
  }
  if (received == 0) {
    return ReceiveAttempt{ReceiveState::eof, 0, 0};
  }

#ifdef _WIN32
  const int err = WSAGetLastError();
  if (err == WSAEWOULDBLOCK) {
    return ReceiveAttempt{ReceiveState::would_block, 0, err};
  }
  return ReceiveAttempt{ReceiveState::error, 0, err};
#else
  const int err = errno;
  if (err == EAGAIN || err == EWOULDBLOCK) {
    return ReceiveAttempt{ReceiveState::would_block, 0, err};
  }
  if (err == EINTR) {
    return ReceiveAttempt{ReceiveState::interrupted, 0, err};
  }
  return ReceiveAttempt{ReceiveState::error, 0, err};
#endif
}

